function isoDate(date = new Date()) { const d = new Date(date); d.setHours(12,0,0,0); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}` }
function addDays(value, amount) { const d = new Date(`${value}T12:00:00`); d.setDate(d.getDate()+Number(amount)); return isoDate(d) }
function nightsBetween(start,end) { if(!start||!end) return 0; return Math.max(1,Math.round((new Date(`${end}T12:00:00`)-new Date(`${start}T12:00:00`))/DAY)) }
function money(value,currency="ARS") { const n=Number(value||0); return currency==="USD"?`US$ ${n.toLocaleString("es-AR",{maximumFractionDigits:2})}`:`$ ${Math.round(n).toLocaleString("es-AR")}` }
function shortDate(v) { return v?new Date(`${v}T12:00:00`).toLocaleDateString("es-AR",{day:"2-digit",month:"short"}):"—" }
function initials(name="Hotel") { return String(name).split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()).join("")||"HL" }
function safeJson(v,fallback) { if(!v) return fallback; if(typeof v==="object") return v; try{return JSON.parse(v)}catch{return fallback} }
